-- 111: Original BrillaPrep 4PH1 beta questions, part 1.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_001', 'topic_edx_4ph1_1', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A car changes velocity from 5 m/s to 17 m/s in 4 s. Calculate its acceleration.', 'multiple_choice', '["A. 3 m/s²","B. 4.25 m/s²","C. 5.5 m/s²","D. 12 m/s²"]', 'A', 'Acceleration is change in velocity divided by time: (17 − 5) ÷ 4 = 3 m/s². Therefore the correct answer is A: 3 m/s².', 'easy', 1, 1, 90, 'st_edx_4ph1_1', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_002', 'topic_edx_4ph1_1', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A 6 kg object accelerates at 2.5 m/s². Calculate the resultant force.', 'multiple_choice', '["A. 2.4 N","B. 15 N","C. 8.5 N","D. 30 N"]', 'B', 'Newton’s second law gives F = ma = 6 × 2.5 = 15 newtons. Therefore the correct answer is B: 15 N.', 'medium', 2, 2, 90, 'st_edx_4ph1_1', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_003', 'topic_edx_4ph1_1', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Calculate the momentum of a 900 kg car moving at 20 m/s.', 'multiple_choice', '["A. 45 kg m/s","B. 920 kg m/s","C. 18,000 kg m/s","D. 180,000 kg m/s"]', 'C', 'Momentum equals mass multiplied by velocity: 900 × 20 = 18,000 kg m/s. Therefore the correct answer is C: 18,000 kg m/s.', 'hard', 1, 1, 90, 'st_edx_4ph1_1', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_004', 'topic_edx_4ph1_1', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A force of 40 N acts 0.25 m from a pivot. Calculate the moment.', 'multiple_choice', '["A. 0.00625 N m","B. 40.25 N m","C. 160 N m","D. 10 N m"]', 'D', 'Moment equals force multiplied by perpendicular distance: 40 × 0.25 = 10 N m. Therefore the correct answer is D: 10 N m.', 'easy', 2, 2, 90, 'st_edx_4ph1_1', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_005', 'topic_edx_4ph1_1', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Why does a parachutist eventually fall at terminal velocity?', 'multiple_choice', '["A. Drag grows until it equals weight","B. Weight becomes zero","C. Mass is lost continuously","D. Gravity switches off"]', 'A', 'At terminal velocity upward drag balances downward weight, so resultant force and acceleration are zero. Therefore the correct answer is A: Drag grows until it equals weight.', 'medium', 3, 3, 90, 'st_edx_4ph1_1', 'Explain', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_006', 'topic_edx_4ph1_2', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A 12 V supply drives 3 A through a resistor. Calculate its resistance.', 'multiple_choice', '["A. 0.25 Ω","B. 4 Ω","C. 9 Ω","D. 36 Ω"]', 'B', 'Ohm’s law gives R = V/I = 12 ÷ 3 = 4 ohms. Therefore the correct answer is B: 4 Ω.', 'hard', 2, 2, 90, 'st_edx_4ph1_2', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_007', 'topic_edx_4ph1_2', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Calculate the charge transferred by a 2.5 A current in 40 s.', 'multiple_choice', '["A. 16 C","B. 42.5 C","C. 100 C","D. 1,000 C"]', 'C', 'Charge equals current multiplied by time: Q = It = 2.5 × 40 = 100 coulombs. Therefore the correct answer is C: 100 C.', 'easy', 1, 1, 90, 'st_edx_4ph1_2', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_008', 'topic_edx_4ph1_2', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'An appliance uses 230 V and 4 A. Calculate its power.', 'multiple_choice', '["A. 57.5 W","B. 234 W","C. 2,300 W","D. 920 W"]', 'D', 'Electrical power is P = VI = 230 × 4 = 920 watts. Therefore the correct answer is D: 920 W.', 'medium', 2, 2, 90, 'st_edx_4ph1_2', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_009', 'topic_edx_4ph1_2', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Why are domestic appliances connected in parallel?', 'multiple_choice', '["A. Each receives full supply voltage and works independently","B. Current must be identical in every appliance","C. One switch controls every circuit","D. Total resistance always increases"]', 'A', 'Parallel branches share the supply potential difference and one open branch does not break the others. Therefore the correct answer is A: Each receives full supply voltage and works independently.', 'hard', 1, 1, 90, 'st_edx_4ph1_2', 'Explain', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_010', 'topic_edx_4ph1_2', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What is the purpose of a fuse?', 'multiple_choice', '["A. It raises the supply voltage","B. It melts and breaks the circuit if current is too high","C. It stores electrical charge permanently","D. It makes live wires safe to touch"]', 'B', 'Excess current heats the fuse wire until it melts, interrupting the circuit before dangerous overheating. Therefore the correct answer is B: It melts and breaks the circuit if current is too high.', 'easy', 3, 3, 90, 'st_edx_4ph1_2', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_011', 'topic_edx_4ph1_3', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A wave has frequency 50 Hz and wavelength 0.40 m. Calculate its speed.', 'multiple_choice', '["A. 0.008 m/s","B. 50.4 m/s","C. 20 m/s","D. 125 m/s"]', 'C', 'Wave speed is v = fλ = 50 × 0.40 = 20 m/s. Therefore the correct answer is C: 20 m/s.', 'medium', 1, 1, 90, 'st_edx_4ph1_3', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_012', 'topic_edx_4ph1_3', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Which electromagnetic wave is commonly used for satellite communication?', 'multiple_choice', '["A. Ultraviolet","B. Gamma rays","C. Visible red only","D. Microwaves"]', 'D', 'Selected microwave frequencies pass through the atmosphere and can carry modulated communication signals. Therefore the correct answer is D: Microwaves.', 'hard', 2, 2, 90, 'st_edx_4ph1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_013', 'topic_edx_4ph1_3', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What happens to light entering glass from air at an angle?', 'multiple_choice', '["A. It slows and bends toward the normal","B. It speeds up and bends away","C. Its frequency becomes zero","D. It always reflects completely"]', 'A', 'Glass has a higher refractive index, so light slows while frequency stays constant and the ray bends toward the normal. Therefore the correct answer is A: It slows and bends toward the normal.', 'easy', 1, 1, 90, 'st_edx_4ph1_3', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_014', 'topic_edx_4ph1_3', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'What property determines the pitch of a sound?', 'multiple_choice', '["A. Amplitude","B. Frequency","C. Speed only","D. Wavelength only regardless of speed"]', 'B', 'Higher-frequency vibrations are heard as higher pitch, while amplitude mainly affects loudness. Therefore the correct answer is B: Frequency.', 'medium', 2, 2, 90, 'st_edx_4ph1_3', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_015', 'topic_edx_4ph1_3', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Which condition is required for total internal reflection?', 'multiple_choice', '["A. Light enters a denser medium below normal","B. Frequency must be zero","C. Light travels from higher to lower refractive index above the critical angle","D. The surface must absorb all light"]', 'C', 'Beyond the critical angle in the optically denser medium, no refracted ray emerges. Therefore the correct answer is C: Light travels from higher to lower refractive index above the critical angle.', 'hard', 3, 3, 90, 'st_edx_4ph1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_016', 'topic_edx_4ph1_4', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A machine receives 500 J and transfers 350 J usefully. Calculate its efficiency.', 'multiple_choice', '["A. 30%","B. 143%","C. 850%","D. 70%"]', 'D', 'Efficiency is useful output divided by total input: 350 ÷ 500 × 100 = 70%. Therefore the correct answer is D: 70%.', 'easy', 2, 2, 90, 'st_edx_4ph1_4', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_017', 'topic_edx_4ph1_4', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A 25 N force moves a box 6 m in its direction. Calculate the work done.', 'multiple_choice', '["A. 150 J","B. 4.17 J","C. 31 J","D. 300 J"]', 'A', 'Work done equals force times distance moved in the force direction: 25 × 6 = 150 J. Therefore the correct answer is A: 150 J.', 'medium', 1, 1, 90, 'st_edx_4ph1_4', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_018', 'topic_edx_4ph1_4', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Calculate the gravitational potential energy gained by 3 kg raised 5 m, using g = 10 N/kg.', 'multiple_choice', '["A. 15 J","B. 150 J","C. 50 J","D. 600 J"]', 'B', 'Gravitational potential energy change is mgh = 3 × 10 × 5 = 150 J. Therefore the correct answer is B: 150 J.', 'hard', 2, 2, 90, 'st_edx_4ph1_4', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_019', 'topic_edx_4ph1_4', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'A device transfers 1,200 J in 30 s. Calculate its power.', 'multiple_choice', '["A. 0.025 W","B. 36 W","C. 40 W","D. 36,000 W"]', 'C', 'Power is energy transferred per unit time: 1,200 ÷ 30 = 40 watts. Therefore the correct answer is C: 40 W.', 'easy', 1, 1, 90, 'st_edx_4ph1_4', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ph1_b001_020', 'topic_edx_4ph1_4', 'subj_edexcel_igcse_physics', 'edexcel_igcse', 'Which energy resource is renewable?', 'multiple_choice', '["A. Coal","B. Natural gas","C. Uranium fuel","D. Wind"]', 'D', 'Wind is continually replenished by atmospheric processes, unlike finite fossil or nuclear fuels. Therefore the correct answer is D: Wind.', 'medium', 3, 3, 90, 'st_edx_4ph1_4', 'Identify', 'AO2', 'board_edexcel');
